const rows = $input.all().map(i => i.json);

function toDateOnly(value) {
  if (!value) return null;

  const d = new Date(value);
  if (isNaN(d.getTime())) return null;

  return new Date(Date.UTC(
    d.getUTCFullYear(),
    d.getUTCMonth(),
    d.getUTCDate()
  ));
}

function toBool(v, d = false) {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;

  if (typeof v === "string") {
    const s = v.trim().toLowerCase();

    if (["true", "1", "yes", "y"].includes(s)) return true;
    if (["false", "0", "no", "n", ""].includes(s)) return false;
  }

  if (v === null || v === undefined) return d;

  return d;
}

const today = new Date();
const todayDateOnly = new Date(Date.UTC(
  today.getUTCFullYear(),
  today.getUTCMonth(),
  today.getUTCDate()
));

const MS_PER_DAY = 24 * 60 * 60 * 1000;

return rows.map(r => {
  const createdDateOnly = toDateOnly(r.createdAt);

  let daysFromCreation = null;
  if (createdDateOnly) {
    daysFromCreation = Math.floor((todayDateOnly - createdDateOnly) / MS_PER_DAY);
  }

  return {
    json: {
      customerId: r.id ?? null,
      customerName: r.companyName ?? "",
      email: r.email ?? null,
      website: r.website ?? null,
      location: r.location ?? null,
      creationDate: r.createdAt ?? null,
      isActive: r.isActive ?? null,
      isSubscribed: toBool(r.isSubscribed, false),
      daysFromCreation: daysFromCreation
    }
  };
});

const rows = $input.all().map(i => i.json);

// ---------- helpers ----------
const esc = (v) =>
  String(v ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");

const toInt = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

const sortByName = (a, b) => (a.name || "").localeCompare(b.name || "");

// Flexible boolean parser
function toBool(v, d = false) {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    if (["true", "1", "yes", "y"].includes(s)) return true;
    if (["false", "0", "no", "n"].includes(s)) return false;
  }
  return d;
}

// Check subscription / free-plan status from different possible fields
function getIsSubscribed(r) {
  // direct boolean fields
  if (r.isSubscribed !== undefined) return toBool(r.isSubscribed);
  if (r.subscribed !== undefined) return toBool(r.subscribed);
  if (r.hasSubscription !== undefined) return toBool(r.hasSubscription);

  // plan-based fields
  const plan = String(r.plan ?? r.subscriptionPlan ?? r.planName ?? "").trim().toLowerCase();
  if (plan) {
    // treat free / trial / basic as NOT subscribed
    if (["free", "trial", "basic"].includes(plan)) return false;
    return true;
  }

  // default if not found
  return false;
}

// Build normalized entry
function makeEntry(r) {
  const isSubscribed = getIsSubscribed(r);

  return {
    name: String(
      r.customerName ??
      r.companyName ??
      r.name ??
      r.fullName ??
      "Unknown"
    ),
    email: String(r.email ?? ""),
    days: toInt(r.daysFromCreation ?? r.daysFromRegistration, 0),
    isSubscribed,
    plan: String(r.plan ?? r.subscriptionPlan ?? r.planName ?? (isSubscribed ? "Paid" : "Free")),
    createdAt: String(r.createdAt ?? r.creationDate ?? r.registrationDate ?? "")
  };
}

const all = rows.map(makeEntry);

// Buckets
const b1 = [];          // day 1
const b7_free = [];     // day 7 and not subscribed
const b14_free = [];    // day 14 and not subscribed
const b30_free = [];    // day 30 and not subscribed

for (const e of all) {
  if (e.days === 1) b1.push(e);
  if (e.days === 7 && !e.isSubscribed) b7_free.push(e);
  if (e.days === 14 && !e.isSubscribed) b14_free.push(e);
  if (e.days === 30 && !e.isSubscribed) b30_free.push(e);
}

// Sort
b1.sort(sortByName);
b7_free.sort(sortByName);
b14_free.sort(sortByName);
b30_free.sort(sortByName);

// KPI totals
const totalScanned = all.length;
const totalMatched = b1.length + b7_free.length + b14_free.length + b30_free.length;
const totalFreeMatched = b7_free.length + b14_free.length + b30_free.length;

// Timestamp
const generatedAt = new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC";

// ---------- render ----------
function kpiCard(label, value) {
  return `
  <td style="width:25%;padding:6px;">
    <div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 14px;">
      <div style="font-size:12px;line-height:16px;color:#6b7280;margin-bottom:6px;">${esc(label)}</div>
      <div style="font-size:22px;line-height:26px;font-weight:800;color:#111827;">${esc(value)}</div>
    </div>
  </td>`;
}

function renderTable(items, emptyText) {
  if (!items.length) {
    return `<div style="color:#6b7280;font-size:13px;line-height:18px;">${esc(emptyText)}</div>`;
  }

  const rowsHtml = items.map((e) => {
    const name = esc(e.name);
    const email = esc(e.email);
    const days = esc(e.days);
    const plan = esc(e.plan);
    const sub = e.isSubscribed ? "Yes" : "No";

    return `
      <tr>
        <td style="padding:10px 10px;border-top:1px solid #eef2f7;font-size:13px;color:#111827;">
          <div style="font-weight:700;">${name}</div>
          ${email ? `<div style="color:#6b7280;font-size:12px;margin-top:2px;">${email}</div>` : ``}
        </td>
        <td align="center" style="padding:10px 10px;border-top:1px solid #eef2f7;font-size:13px;color:#111827;">${days}</td>
        <td align="center" style="padding:10px 10px;border-top:1px solid #eef2f7;font-size:13px;color:#111827;">${esc(sub)}</td>
        <td align="center" style="padding:10px 10px;border-top:1px solid #eef2f7;font-size:13px;color:#111827;">${plan}</td>
      </tr>`;
  }).join("");

  return `
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"
           style="border-collapse:collapse;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
      <tr style="background:#f8fafc;">
        <th align="left" style="padding:10px 10px;font-size:12px;color:#6b7280;font-weight:700;">Customer</th>
        <th align="center" style="padding:10px 10px;font-size:12px;color:#6b7280;font-weight:700;">Days</th>
        <th align="center" style="padding:10px 10px;font-size:12px;color:#6b7280;font-weight:700;">Subscribed</th>
        <th align="center" style="padding:10px 10px;font-size:12px;color:#6b7280;font-weight:700;">Plan</th>
      </tr>
      ${rowsHtml}
    </table>`;
}

function sectionCard(title, subtitle, items, emptyText) {
  return `
  <div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:14px;padding:14px 14px;margin-top:14px;">
    <div style="display:flex;align-items:flex-end;justify-content:space-between;gap:10px;">
      <div>
        <div style="font-size:15px;line-height:20px;font-weight:800;color:#111827;">${esc(title)} <span style="color:#2563eb;">(${items.length})</span></div>
        <div style="font-size:12.5px;line-height:18px;color:#6b7280;margin-top:4px;">${esc(subtitle)}</div>
      </div>
    </div>
    <div style="margin-top:12px;">
      ${renderTable(items, emptyText)}
    </div>
  </div>`;
}

const subject = `SolveStack • Automation Customer Report (${generatedAt})`;

const body = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <meta name="x-apple-disable-message-reformatting" />
  <meta name="format-detection" content="telephone=no,address=no,email=no,date=no,url=no" />
  <title>${esc(subject)}</title>
</head>

<body style="margin:0;padding:0;background:#f3f4f6;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f3f4f6;">
    <tr>
      <td align="center" style="padding:24px 12px;">
        <table role="presentation" width="720" cellspacing="0" cellpadding="0" border="0"
               style="width:720px;max-width:720px;background:#ffffff;border-radius:16px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;box-shadow:0 8px 22px rgba(0,0,0,0.06);">

          <!-- Top bar -->
          <tr>
            <td style="height:6px;background:#2563eb;line-height:6px;font-size:0;">&nbsp;</td>
          </tr>

          <!-- Header -->
          <tr>
            <td style="padding:18px 20px;background:#ffffff;">
              <div style="font-size:12px;color:#6b7280;letter-spacing:0.2px;">SolveStack Operations</div>
              <div style="font-size:20px;line-height:26px;font-weight:900;color:#111827;margin-top:6px;">
                Customer Cohorts Report
              </div>
              <div style="font-size:12.5px;line-height:18px;color:#6b7280;margin-top:6px;">
                Generated: ${esc(generatedAt)}
              </div>
            </td>
          </tr>

          <!-- KPI strip -->
          <tr>
            <td style="padding:0 14px 16px 14px;background:#ffffff;">
              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border-collapse:collapse;">
                <tr>
                  ${kpiCard("Customers scanned", totalScanned)}
                  ${kpiCard("Matched rules (sum)", totalMatched)}
                  ${kpiCard("Free-plan matches", totalFreeMatched)}
                  ${kpiCard("Day 7 • Free plan", b7_free.length)}
                </tr>
              </table>
            </td>
          </tr>

          <!-- Content -->
          <tr>
            <td style="padding:0 14px 18px 14px;background:#f8fafc;">

              ${sectionCard(
                "1 day after registration",
                "New customer cohort (daysFromCreation = 1).",
                b1,
                "No customers matched day 1 today."
              )}

              ${sectionCard(
                "1 week after registration • Free plan",
                "Follow-up cohort (daysFromCreation = 7 AND not subscribed).",
                b7_free,
                "No customers matched day 7 / free-plan today."
              )}

              ${sectionCard(
                "2 weeks after registration • Free plan",
                "Follow-up cohort (daysFromCreation = 14 AND not subscribed).",
                b14_free,
                "No customers matched day 14 / free-plan today."
              )}

              ${sectionCard(
                "1 month after registration • Free plan",
                "Follow-up cohort (daysFromCreation = 30 AND not subscribed).",
                b30_free,
                "No customers matched day 30 / free-plan today."
              )}

              <div style="margin-top:14px;font-size:12px;line-height:18px;color:#6b7280;padding:0 4px;">
                Tip: If counts look off, verify that <b>daysFromCreation</b> is calculated using date-only logic rather than full timestamp logic.
              </div>

            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="padding:16px 20px;background:#ffffff;border-top:1px solid #eef2f7;">
              <div style="font-size:12px;line-height:18px;color:#6b7280;">
                Internal report for customer automation monitoring.
              </div>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

return [{
  json: {
    subject,
    body
  }
}];

const rows = $input.all().map(i => i.json);

const b1 = [];
const b7 = [];
const b14 = [];
const b30 = [];

for (const r of rows) {
  const days = Number(r.daysFromCreation ?? 0);
  const isSubscribed = r.isSubscribed === true;

  if (days === 1) b1.push(r);
  if (days === 7 && !isSubscribed) b7.push(r);
  if (days === 14 && !isSubscribed) b14.push(r);
  if (days === 30 && !isSubscribed) b30.push(r);
}

function line(items) {
  if (!items.length) return "• None";
  return items.map(r =>
    `• ${r.customerName ?? "Unknown"} — ${r.email ?? "no email"}`
  ).join("\n");
}

const message = `*SolveStack Daily Customer Report*
Generated: ${new Date().toISOString()}

*Summary*
• Customers scanned: ${rows.length}
• Day 1: ${b1.length}
• Day 7 free: ${b7.length}
• Day 14 free: ${b14.length}
• Day 30 free: ${b30.length}

*Day 1 customers*
${line(b1)}

*Day 7 free-plan customers*
${line(b7)}

*Day 14 free-plan customers*
${line(b14)}

*Day 30 free-plan customers*
${line(b30)}`;

return [
  {
    json: {
      text: message
    }
  }
];
